import {actions} from './actions.js';
import {repository,exportData,dayKey} from './store.js';
import {resetLevels} from './testing.js';
import {isTestMode,selectProfile,advanceTestDay} from './profile.js';
export function createTestingUI(ctx){const e=ctx.esc;let reviewed=null;
 const entry=()=>`<article class="card"><span class="eyebrow">TESTING // DATA SAFETY</span><h2>Room to experiment.</h2><p class="muted">Try tomorrow, rewards, and workout proofs in an isolated test profile. Review every reset before it runs.</p><button data-action="testingTools">Testing tools ↗</button></article>`;
 function tools(){ctx.modal('Testing tools / '+(isTestMode()?'TEST PROFILE':'REAL PROFILE'),`<div class="notice">${isTestMode()?'TEST MODE · separate database · simulated activity does not affect real progress.':'Your real profile is open. Switch to Test Mode to simulate activity safely.'}</div><div class="actions"><button class="white" data-action="switchTestProfile">${isTestMode()?'Return to real profile':'Enter isolated Test Mode'}</button><button data-action="export">Export Backup ↓</button></div>${isTestMode()?`<h3>Test controls</h3><p class="legend">Test date: ${dayKey()}. These actions create synthetic records only in the test database.</p><div class="actions"><button data-action="testTomorrow">Simulate tomorrow / daily reset</button><button data-action="testXP">Award 100 test XP / quest</button><button data-action="testReadiness">Set low test readiness</button><button data-action="testWorkout">Complete a test workout / badge</button><button data-action="testBoss">Prove Ground Control boss</button><button data-action="muscleMap">Inspect Dominance / Muscle Map</button></div>`:''}<h3>Choose a reset level</h3>${Object.entries(resetLevels).map(([id,name])=>`<div class="row"><div class="row-main"><h3>${name}</h3><p>${{today:'Current date only. Earlier days and templates stay.',active:'Unfinished workout instances only. Completed records stay.',progression:'Clear progression and rewards; keep workout history and templates.',full:'Start over. Clear user history, rewards, metrics, daily states, and generated schedules.'}[id]}</p></div><button data-action="resetOptions" data-level="${id}">Review reset</button></div>`).join('')}<p class="legend">The built-in library, skill trees, app configuration, and system definitions survive resets. Resetting progression establishes a baseline so retained old workouts cannot immediately re-award it.</p>`)}
 async function options(level){if(level==='full'){ctx.modal('Full reset / keep your creations?',`<p>Keep my custom workouts and routines?</p><p class="legend">Yes keeps workout and routine templates, custom exercise definitions, and recurring personal-time patterns. Completion records and generated daily schedules are still cleared.</p><div class="actions"><button data-action="resetPreview" data-level="full" data-keep="true">Yes / keep my creations</button><button data-action="resetPreview" data-level="full" data-keep="false">No / reset user creations too</button></div>`)}else await preview(level,true)}
 async function preview(level,keepCustom){reviewed=await actions.dispatch('previewReset',{level,keepCustom});ctx.modal(e(reviewed.label)+' / review',`<div class="notice">${isTestMode()?'ISOLATED TEST PROFILE':'REAL USER PROFILE'} · ${reviewed.date}</div><p>${level==='today'?'Today’s completions, workouts, water, quests, readiness, and soreness will reset. Schedule blocks remain planned. Earlier dates stay.':level==='active'?'Unfinished sessions and their temporary records will be removed. Completed history stays.':level==='progression'?'XP, coins, purchases, badges, quests, PRs, Dominance proofs, and mastery will clear. Existing workouts remain in history but will not regenerate progression.':'Workout, water and routine histories, quests, rewards, badges, mastery, PRs, recovery, body metrics, daily states, preferences, and generated schedules will clear. '+(keepCustom?'Custom workouts and routines will stay.':'User-created templates and routines will clear too.')}</p><h3>Records to remove</h3>${Object.entries(reviewed.counts).map(([s,n])=>`<div class="reset-count"><span>${e(s.replace(/([A-Z])/g,' $1').toLowerCase())}</span><strong>${n}</strong></div>`).join('')||'<p class="muted">No removable records at this level.</p>'}<p class="legend">Keep: built-in exercise library, built-in skill trees, app configuration, and achievement definitions. ${level==='full'?'App configuration stays; user progress returns to first launch.':'Templates and settings stay.'}</p><button type="button" data-action="export">Export Backup before resetting ↓</button><form class="fields" style="margin-top:20px"><label><input style="width:auto" type="checkbox" name="ack" required> I reviewed what will be deleted from this ${isTestMode()?'test':'real'} profile.</label>${ctx.field('Type RESET KITTY to confirm','confirmation','text','','required autocomplete="off" pattern="RESET KITTY"')}<button class="reset-confirm">Confirm reviewed reset</button></form>`,async f=>{const result=await actions.dispatch('executeReset',{preview:reviewed,confirmation:f.get('confirmation'),acknowledged:f.has('ack'),backupOffered:true});ctx.downloadBackup(result.previous,'-before-reset');ctx.toast('Reviewed reset complete. A safety backup was exported.');if(level==='full')setTimeout(()=>globalThis.location.reload(),80)})}
 async function testWorkout(){const ex=(await repository.all('exercises')).find(e=>e.id==='db-triceps');const s=await actions.dispatch('startSession',{kind:'Extra',name:'TEST / controlled triceps workout',exercises:[{exerciseId:ex.id,name:ex.name,sets:1,reps:8,weight:5}]});await actions.dispatch('logSet',{sessionId:s.id,exercise:0,reps:8,weight:5,difficulty:6,form:true,tempoControlled:true,pain:false,notes:'TEST / synthetic workout'});await actions.dispatch('completeSession',{sessionId:s.id,difficulty:6})}
 async function testBoss(){const skill=(await repository.all('skillDefinitions')).find(s=>s.id==='push');for(const level of skill.levelDefinitions.slice(0,5))for(let i=0;i<level.sessions;i++)for(const r of level.requirements){const date=new Date();date.setDate(date.getDate()+Number(localStorage.getItem('kitty-test-days')||0)-2+i);await actions.dispatch('recordDominanceAttempt',{attempt:{skill:skill.id,levelId:level.id,trial:r.id,date:dayKey(date),sets:r.sets,reps:r.reps||0,seconds:r.seconds||0,distance:r.distance||0,load:r.load||0,difficulty:6,form:true,tempo:true,pain:false,notes:'TEST / synthetic boss proof'}})}}
 async function handleAction(b){switch(b.dataset.action){case 'testingTools':tools();break;case 'switchTestProfile':selectProfile(!isTestMode());break;case 'resetOptions':await options(b.dataset.level);break;case 'resetPreview':await preview(b.dataset.level,b.dataset.keep==='true');break;case 'testTomorrow':advanceTestDay();break;case 'testXP':await actions.dispatch('testAwardXP',{amount:100});await actions.dispatch('syncGame');await ctx.refresh();tools();ctx.toast('Test quest completed / 100 test XP awarded.');break;case 'testReadiness':if(!isTestMode())throw Error('Enter Test Mode first.');await actions.dispatch('logSoreness',{muscle:'Triceps',rating:4});await ctx.refresh();tools();ctx.toast('Test Triceps soreness set to 4/4.');break;case 'testWorkout':if(!isTestMode())throw Error('Enter Test Mode first.');await testWorkout();await ctx.refresh();tools();ctx.toast('Synthetic test workout completed.');break;case 'testBoss':if(!isTestMode())throw Error('Enter Test Mode first.');await testBoss();await ctx.refresh();tools();ctx.toast('Ground Control test boss cleared.');break;default:return false}return true}
 return {entry,handleAction};
}
